    static let hatchetDisputeV1 = SmallCases.make(
        key: "story.hatchetDispute",
        category: .violent,
        headlines: ["Property Line Quarrel on Gravel Lane Ends in Fatal Wound", "Splitting Maul Found Behind Truck Seat"],
        law: "murder2",
        threshold: 8,
        spec: "Unlawfully killed {V} with malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A 911 caller reported {V} down beside a shared gravel lane at dusk on {DATE}, after weeks of quarreling with {D}, a neighbor, over where a fence belonged. {V} had one deep wound to the upper body. A splitting maul with blood on its head was behind the seat of {D}'s truck. {DL} says {V} swung a fence post first.",
        state: [E(.physical, 3, "Splitting Maul", "Blood matching {V} on the head of a maul found behind the seat of {D}'s truck.", .search), E(.digital, 3, "911 Recording", "A caller hears raised voices, a crack, then silence from the lane."), E(.forensic, 2, "Medical Examiner", "One deep wound to the upper body.")],
        defense: [E(.physical, 1, "Fence Post", "A splintered post lay in the gravel near {V}'s hand.")],
        role: "Sheriff's detective",
        exam: [.direct("What did you find when you arrived at the gravel lane?", "\"{V} was down beside the lane at dusk with one deep wound to the upper body. A fence post lay splintered in the gravel nearby.\""), .direct("What was the background between {V} and {DL}?", "\"Weeks of quarreling over where a fence line belonged. Deputies had heard about the dispute from other neighbors before this night.\""), .direct("What did the 911 recording capture?", "\"Raised voices, a sharp crack, and then silence from the lane. The caller was down the road and could not see details.\""), .direct("What was found in {DL}'s truck?", "\"A splitting maul behind the seat, with blood on the head. Lab testing matched that blood to {V}.\""), .direct("What did the medical examiner conclude?", "\"One deep wound to the upper body. The wound is consistent with a heavy chopping tool like that maul.\""), .direct("What did {DL} tell you at the scene?", "\"That {V} swung a fence post first and {D} defended {D.himself}. {D} pointed to the splintered post near {V}'s hand.\""), .cross("Did anyone see the actual moment of the blow?", "\"No. The caller heard it from down the lane. I have no eyewitness to the swing itself.\""), .cross("Was the fence post near {V}'s hand?", "\"Yes, a splintered post lay in the gravel close to {V}'s hand. I photographed its position.\""), .cross("Did {DL} stay at the scene?", "\"{D} was still near the lane when deputies arrived and did not run. {D} spoke with us.\""), .cross("Did {V} have any wound on a hand?", "\"I noted splinters in a glove. I could not tell from the scene how they got there.\""), .cross("Did {DL} deny having the maul in the truck?", "\"No. {D} said it was for splitting wood, which people in that area do all the time.\"")],
        defenseRole: "Caller down the lane",
        defenseExam: [.direct("Where were you when you called 911?", "\"Down the lane, near my own gate. I was walking my dog and heard raised voices.\""), .direct("What did you hear?", "\"Two people shouting about the fence. Then a crack, and then it went quiet.\""), .direct("Did you recognize the voices?", "\"Yes. One was {V} and the other was {D}. They had argued out there before.\""), .direct("Who sounded angrier?", "\"Both, honestly. {V} was loud and sharp, and I heard something scrape in the gravel.\""), .direct("What did you do next?", "\"I called 911 and hurried up the lane. I found {V} down and {D} standing close, upset.\""), .direct("How did {DL} act?", "\"Shaken. {D} was saying 'I did not mean it' and tried to talk to {V}.\""), .cross("Did you see anyone swing anything?", "\"No. It was dusk and I was too far away.\""), .cross("Did you see a fence post in {V}'s hand?", "\"I saw one on the ground near {V} when I got there.\""), .cross("Did you hear {V} threaten {DL}?", "\"I heard shouting. I could not make out every word.\""), .cross("Was {DL} holding the maul when you arrived?", "\"I did not notice. I looked at {V}.\""), .cross("Do you like either neighbor more than the other?", "\"No. I get along with both of them.\"")],
        theory: ("{D} grabbed a maul and killed a neighbor over a fence line.", "A neighbor who swung a post and was met with what was in reach."),
        allocution: "\"I wish I had just driven away.\"",
        truths: ("A voicemail {DL} left {V} the week before said {V.he} would regret moving that fence.", "{V}'s glove held fresh splinters from the post, and {V}'s palm print was on it."),
        defendant: [.direct("What was the argument about?", "\"A fence line between our properties. {V} insisted the line sat where I did not think it did, and it had gone on for weeks.\""), .direct("What happened on the lane at dusk?", "\"We met there and argued again. {V} got louder and grabbed a fence post from the gravel.\""), .direct("What did {V} do with the post?", "\"Swung it at me. I saw it coming and had the maul in my hand because I had been splitting wood.\""), .direct("What did you do?", "\"I raised the maul to block and swung back. I did not think. It was over in a second.\""), .direct("What did you do afterward?", "\"I stood there shaking and tried to help. I did not run, and I told the deputies what had happened.\""), .direct("Do you regret it?", "\"Every day. I never wanted anyone hurt over a fence, and I wish I had walked away.\""), .cross("A voicemail you left said {V} would regret moving the fence, didn't it?", "\"Yes. I was angry and I said it. I meant it as a complaint, not a threat to hurt anyone.\""), .cross("You had a maul behind your truck seat, didn't you?", "\"Yes. I use it for firewood and keep it in the truck.\""), .cross("The blood on the maul matched {V}, didn't it?", "\"So I have been told. That is the maul I swung.\""), .cross("You could have driven away instead, couldn't you?", "\"In hindsight, yes. It happened too fast for me to think about it.\""), .cross("{V} did not have a weapon like a maul, did {V.he}?", "\"{V} had a heavy fence post, which can hurt as badly.\"")],
        openings: ("After weeks of quarreling over a fence line, {V} was found down beside a gravel lane with one deep wound. A maul with {V}'s blood was behind the seat of {D}'s truck. The State will show the maul, the 911 call, and the medical examiner's findings.", "A splintered fence post lay in the gravel near {V}'s hand. {D} says {V} swung first, and a neighbor down the lane heard the shouting before the crack."),
        closings: ("A maul behind the seat with {V}'s blood on its head, a threatening voicemail the week before, and one deep wound. {D} ended a fence quarrel with a blow.", "A splintered post by {V}'s hand and glove, and an argument that boiled over. The State has not disproved that {D} acted to defend {D.himself}."),
        timeline: [(-21, "Fence stakes appear along the shared lane."), (0, "6:40 p.m.: shouting on the lane."), (0, "6:48 p.m.: the 911 call."), (0, "9 p.m.: {DL} is arrested at home.")],
        identified: "A 911 caller and a bloody tool.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        doctrines: ["selfDefense", "imperfectSelfDefense", "lesserIncluded"])

    static let waterTowerClimbV1 = SmallCases.make(
        key: "story.waterTowerClimb",
        category: .property,
        headlines: ["Teens Scale Grain Elevator for Sunrise Photos, Cited for Trespass", "Co-op Night Manager Spots Flashlights High on the Elevator"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a farm cooperative, after being notified not to enter, on {DATE}.",
        ages: 18...24,
        victim: true,
        summary: "A night manager at a farm co-op saw flashlights near the top of the grain elevator on {DATE}. {D} and two friends had gone through the loading yard and up the stair cage, past a sign reading 'Authorized Personnel Only, No Trespassing.' {D} says a worker waved them through the gate.",
        state: [E(.physical, 3, "Posted Signs", "Signs on the yard gate and at the foot of the stair cage."), E(.video, 2, "Phone Video", "{D} on the roof catwalk: 'best view in the county.'")],
        defense: [E(.statement, 1, "Waved Through", "{DL} says a forklift driver waved the group in.")],
        role: "Co-op manager",
        exam: [.direct("What did you see on the night in question?", "\"I was working late as night manager when I saw flashlights near the top of the grain elevator, bobbing on the catwalk.\""), .direct("Was the yard open to the public?", "\"No. The yard gate was closed and had a sign on it reading Authorized Personnel Only, No Trespassing.\""), .direct("Were there other signs?", "\"Yes. Another sign hung at the foot of the stair cage with the same warning. Both are in the photographs.\""), .direct("Who did you find on the elevator?", "\"Three young people with phones, taking video and photos. {D} was one of them, standing on the roof catwalk.\""), .direct("What does the phone video show?", "\"{D} on the roof catwalk saying it was the best view in the county, and laughing with the others.\""), .direct("Why is climbing the elevator a danger?", "\"Grain dust, narrow stairs, open edges, and no safety lines. Elevators are dangerous places even in daylight.\""), .cross("Was anyone stationed at the gate that night?", "\"A driver was finishing a load near the scale house. That driver was not posted there as a guard.\""), .cross("Did you see anyone wave the group through?", "\"No. I saw the group only after they were on the elevator, so I cannot tell you how they got in.\""), .cross("Was anyone hurt?", "\"Thankfully not. Nobody fell and nothing was damaged, as far as I could tell.\""), .cross("Did the group try to run when you arrived?", "\"No. They came down when I called out, and they were polite and a little embarrassed.\""), .cross("Did the group take anything?", "\"No. We found nothing missing, only three people who should not have been up there.\"")],
        theory: ("{D} climbed a posted grain elevator for photos.", "A young adult who thought a worker had given the nod."),
        allocution: "\"It was a dumb idea. I'm sorry.\"",
        truths: ("{DL} texted a friend, 'wait until the lot clears and we go.'", "The forklift driver later admitted he told the group it was fine to walk in."),
        defendant: [.direct("Why did you go to the grain elevator?", "\"A friend suggested it, and I thought the view from the top would be amazing. It looked like a fun adventure.\""), .direct("How did you get into the yard?", "\"A worker at the gate waved us through. That is what I took it to mean, and we walked in.\""), .direct("Did you see the signs?", "\"I saw one by the stairs. By then we were already inside the yard, and I thought we had been allowed.\""), .direct("Why did you climb anyway?", "\"I figured we had permission, since someone had waved us through. I should have asked someone inside to be sure.\""), .direct("What did you do at the top?", "\"We took pictures and video. I said the view was the best in the county, and we laughed and enjoyed it.\""), .direct("What would you do differently?", "\"I would never go up without clear permission. I see how dangerous it was, and I am sorry for the worry.\""), .cross("Did you ask anyone inside whether you could climb?", "\"No. I did not ask anyone, and I should have, given the signs.\""), .cross("The sign at the stairs said No Trespassing, didn't it?", "\"Yes. I read it, and I kept going anyway. I told myself the wave meant it was fine.\""), .cross("The gate was shut when you got there, wasn't it?", "\"It was closed. I walked through a gate that was shut with a sign on it.\""), .cross("You were on a roof catwalk with no safety line, weren't you?", "\"Yes. That was foolish, and I understand why the co-op was upset.\""), .cross("Can you name the worker who waved you in?", "\"No. I did not get a name. It was dark, and I saw a person near a forklift.\"")],
        openings: ("Three young people with phones went through a posted, shut gate at a farm co-op and climbed a grain elevator after dark. {D} stood on the roof catwalk, past two No Trespassing signs, and called it the best view in the county.", "A worker waved {D} and friends through the gate, and {D} believed the group had permission. A foolish climb is not a trespass when a person honestly thinks the way is open."),
        closings: ("A shut gate, a sign at the gate, a sign at the stairs, and a climb to the roof anyway. {D} saw those warnings and went up without asking anyone.", "A worker waved the group in, no one asked them to leave, and no harm was done. {D} believed the way was open and the State has not shown otherwise."),
        timeline: [(0, "Before dawn: three friends reach the yard."), (0, "5:40 a.m.: they reach the catwalk."), (0, "6 a.m.: deputies are called.")],
        identified: "The night manager's call and a phone video.",
        impact: "That elevator holds the harvest for dozens of farms.",
        genders: ["D": .male])

    static let inspectorCashV1 = SmallCases.make(
        key: "story.inspectorCash",
        category: .whiteCollar,
        headlines: ["Electrical Inspector Charged After Envelope Handed Over at Diner", "Passed Inspections and a Notebook of Dollar Amounts"],
        law: "bribery",
        threshold: 4,
        spec: "As a public officer, accepted cash from a contractor in exchange for passing electrical inspections, on or about {DATE}.",
        ages: 40...60,
        victim: false,
        summary: "An electrical contractor told investigators that {D}, a county electrical inspector, took $200 per job to pass rough-in inspections. On {DATE} an investigator watched an envelope change hands at a diner. Messages between the two set up the meeting. {DL} says the envelope was payment for a used generator {D.he} sold the contractor.",
        state: [E(.video, 3, "Diner Camera", "The contractor slides an envelope under a menu; {D} pockets it."), E(.digital, 2, "Messages", "'Friday, same as last time?' 'Same.'")],
        defense: [E(.document, 2, "Generator Listing", "{DL} posted a used generator for sale two weeks before.")],
        role: "Code compliance investigator",
        exam: [.direct("What did the contractor tell your office?", "\"That a county electrical inspector took $200 per job to pass rough-in inspections. We opened an investigation and set up surveillance.\""), .direct("What did you watch on {DATE}?", "\"At a diner, the contractor slid an envelope under a menu and {D} pocketed it. I watched it from across the room.\""), .direct("What does the diner camera show?", "\"The same handoff, from another angle, with the envelope sliding under the menu and then disappearing into {D}'s jacket.\""), .direct("What did the messages say?", "\"'Friday, same as last time?' and the reply 'Same.' They set up the meeting.\""), .direct("What did {DL} say about the envelope?", "\"That it was payment for a used generator {D} had sold the contractor.\""), .direct("What did you find in {DL}'s glove box?", "\"A notebook listing job addresses with dollar amounts beside each one. It looked like a ledger.\""), .cross("Did you hear what was said at the diner table?", "\"No. I watched from across the room and the camera has no audio of the conversation.\""), .cross("Is it illegal to sell a used generator to a contractor?", "\"No. Private sales between adults are lawful. What matters is whether the envelope was payment for that sale.\""), .cross("Did the generator listing exist before the meeting?", "\"Yes. A listing was posted two weeks before the diner meeting.\""), .cross("Did you find cash in {DL}'s home beyond the envelope?", "\"I found nothing unusual beyond the notebook. I found no hidden stash.\""), .cross("Did the contractor have a reason to blame {DL}?", "\"The contractor was under investigation too. I cannot say whether that colored the account.\"")],
        defenseRole: "Senior county inspector",
        defenseExam: [.direct("What is your role at the county?", "\"I am a senior electrical inspector. I have worked with {D} for years and often cover for {D} on busy days.\""), .direct("What do you know about the generator?", "\"{D} mentioned selling a used generator and posted a listing two weeks before the diner meeting.\""), .direct("Did you see the listing?", "\"Yes. It was online with photos and an asking price. It matched the generator model the contractor later asked about.\""), .direct("What kind of inspector is {DL}?", "\"Strict. {D} fails jobs when the wiring is wrong and does not bend for contractors.\""), .direct("Has anyone ever complained about {DL}?", "\"Contractors grumble about being failed, but I never heard about anyone being offered a pass for money.\""), .direct("How does {DL} keep notes?", "\"In a notebook, with addresses and numbers. We all keep job notes in our own way.\""), .cross("Did you see the envelope change hands?", "\"No. I was not at the diner.\""), .cross("Do inspectors usually sell generators to contractors?", "\"Not usually. It would be unusual.\""), .cross("Did you ever see the notebook amounts?", "\"I saw it once. I did not read the numbers closely.\""), .cross("Did {DL} tell you about the diner meeting?", "\"No.\""), .cross("Have you ever been paid to pass a job?", "\"Never. Not once.\"")],
        theory: ("{D} took cash from a contractor to pass jobs.", "A generator sale between a seller and a buyer."),
        allocution: "\"I made a poor choice. I'm sorry.\"",
        truths: ("A notebook in {DL}'s glove box listed job addresses with dollar amounts beside each.", "The generator serial number matched the listing {DL} posted before the diner meeting."),
        defendant: [.direct("What do you do for the county?", "\"I am an electrical inspector. I check rough-in work on residential jobs before walls are closed.\""), .direct("What was in the envelope?", "\"Payment for a used generator I had sold to the contractor. I had posted a listing for it two weeks earlier.\""), .direct("Why meet at a diner?", "\"The contractor suggested it. It was convenient, and I wanted cash in hand before I handed over the generator.\""), .direct("What about the messages?", "\"'Same as last time' meant we had talked about the generator before. It was about the sale, nothing else.\""), .direct("What was the notebook?", "\"A list of jobs I had inspected, with notes. The numbers were my own reminders, not payments.\""), .direct("Have you ever taken money to pass an inspection?", "\"No. I have failed jobs for bad wiring many times, and contractors do not always like me for it.\""), .cross("The notebook lists addresses with dollar amounts, doesn't it?", "\"Yes. They were my own notes. I understand how it looks.\""), .cross("You pocketed an envelope at a diner, didn't you?", "\"Yes. It held cash from the generator sale.\""), .cross("The contractor says you took $200 a job, doesn't the contractor?", "\"That is what the contractor says. It is not true.\""), .cross("You never wrote a receipt for the generator, did you?", "\"No. We shook hands. I should have written one.\""), .cross("'Same as last time' suggests earlier payments, doesn't it?", "\"It could be read that way, but it referred to earlier talk about the sale.\"")],
        openings: ("A county electrical inspector, {D}, is accused of taking $200 per job to pass inspections. An investigator watched an envelope slide under a menu at a diner and {D} pocket it, and a notebook lists addresses with dollar amounts. The State will show the video and the messages.", "A used generator, an online listing posted two weeks earlier, and a fellow inspector who knows {D} fails bad work. {D} says the envelope was payment for the sale."),
        closings: ("An envelope under a menu, messages that say same as last time, and a notebook of addresses and dollar amounts. {D} was paid to pass jobs.", "A generator listing posted before the diner meeting and an inspector known for failing bad work. The State has not proved the envelope was a bribe."),
        timeline: [(-14, "{DL} lists a used generator for sale."), (-3, "Messages set up the meeting."), (0, "Noon: the diner handoff."), (30, "{DL} is charged.")],
        identified: "A contractor's tip and a diner camera.",
        notDone: ["The generator sale was never checked against the contractor's books."],
        aggravating: ["The offense endangered public safety"],
        mitigating: ["Long public service", "No prior criminal record"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let busDriverYellV1 = SmallCases.make(
        key: "story.busDriverYell",
        category: .publicOrder,
        headlines: ["Parent Pounds on School Bus Door Over Missed Stop", "Disorderly Conduct Charge After Afternoon Bus Confrontation"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct by making a public disturbance at a school bus stop, on {DATE}.",
        ages: 24...55,
        victim: false,
        summary: "On {DATE} a school bus passed the stop where {D}'s child was supposed to get off and let the child out two blocks away in the rain. {D} ran after the bus, pounded on the door, and shouted at the driver while fifteen children watched. The driver called dispatch. {DL} says the driver ignored the stop for the second time that week.",
        state: [E(.video, 3, "Stop-Arm Camera", "{D} slaps the bus door and shouts, with children visible at the windows."), E(.statement, 2, "Bus Monitor", "The monitor says {D} used profanity and would not step back.")],
        defense: [E(.document, 1, "Missed Stop Log", "The route log shows two skipped stops that week.")],
        role: "Transportation supervisor",
        exam: [.direct("What is your role?", "\"I am a transportation supervisor for the school district. I handle bus routes, driver reports, and complaints.\""), .direct("What happened on {DATE}?", "\"A school bus passed the stop where {D}'s child was supposed to get off and let the child out two blocks away in the rain.\""), .direct("What does the stop-arm camera show?", "\"{D} running up and slapping the bus door and shouting, with children visible at the windows.\""), .direct("How many children were on the bus?", "\"Fifteen. They were watching from the windows when {D} confronted the driver.\""), .direct("What did the bus monitor report?", "\"That {D} used profanity and would not step back from the door when asked.\""), .direct("What did the driver do?", "\"The driver called dispatch to report the confrontation, and we reviewed the video.\""), .cross("Did you see the confrontation yourself?", "\"No. I reviewed the camera and the reports. I was not on the street.\""), .cross("Did the route log show skipped stops that week?", "\"Yes. It lists two skipped stops on that route within the same week.\""), .cross("Did {DL} hit anyone?", "\"No. I did not see contact with the driver or with any child.\""), .cross("Did the driver admit anything to a supervisor?", "\"Yes. The driver told a supervisor the stop was skipped to stay on schedule, which is against our rules.\""), .cross("Was the child hurt?", "\"No. The child was let out two blocks away in the rain and was wet but unhurt.\"")],
        theory: ("{D} chased a bus and screamed in front of children.", "A parent whose child was dropped off in the rain."),
        allocution: "\"I was scared and angry. I should have called the office.\"",
        truths: ("{DL} had been told by the office to call, not confront, and still went after the bus.", "The driver admitted to a supervisor that {D.he} skipped the stop to stay on schedule."),
        defendant: [.direct("What did you see that afternoon?", "\"The bus drove past our stop and my child got off two blocks away in the rain. I was waiting at the stop and saw it go by.\""), .direct("How did you feel?", "\"Furious and scared. Rain was coming down and my child had to walk alone in it.\""), .direct("Why did you chase the bus?", "\"I wanted the driver to stop and explain. I ran, caught up at a light, and pounded on the door.\""), .direct("What did you say?", "\"I shouted. I used words I should not have used in front of children. I was not thinking.\""), .direct("Had this happened before?", "\"Yes. It was the second time that week the bus skipped our stop. I had complained once already.\""), .direct("Do you regret it?", "\"Yes. I should have called the office instead of chasing the bus.\""), .cross("You were told to call the office, weren't you?", "\"Yes. Someone told me to call, not confront. I did not listen.\""), .cross("You slapped the door, didn't you?", "\"I pounded on it with my hand. I did not hit anyone.\""), .cross("Fifteen children watched, didn't they?", "\"I know. I did not think about them in the moment.\""), .cross("The monitor asked you to step back, correct?", "\"The monitor asked me to step back. I did not at first.\""), .cross("You used profanity, didn't you?", "\"Yes. I did. I apologize.\"")],
        openings: ("A school bus let {D}'s child out two blocks from the stop in the rain, and {D} ran after the bus, slapped the door, and shouted at the driver while fifteen children watched. The State will show the stop-arm camera and the monitor's account.", "The bus had skipped the stop twice in one week, and the route log proves it. {D} acted on a parent's fear for a child in the rain."),
        closings: ("A parent chased a bus, slapped the door, used profanity, and refused to step back with fifteen children watching. The camera shows it.", "A skipped stop for the second time that week and a child let out in the rain. The State has not proved {D}'s anger crossed into a crime."),
        timeline: [(0, "3:30 p.m.: the bus skips the stop."), (0, "3:35 p.m.: {DL} catches the bus."), (0, "3:50 p.m.: a deputy arrives.")],
        identified: "The bus camera and the driver's call to dispatch.",
        genders: ["D": .male, "V": .male])

