        defense: [E(.statement, 2, "Mist and Tarp", "The boat was under a camouflage tarp with no lights.")],
        role: "Wildlife officer",
        exam: [.direct("What is your role?", "\"I am a wildlife officer. I investigate hunting incidents.\""), .direct("What happened at first light on {DATE}?", "\"{D} fired a shotgun from a duck blind at a shape on the lake. It was {V}, fishing from a boat, and {V} died.\""), .direct("What did the medical examiner find?", "\"A single shotgun wound to the chest.\""), .direct("What about the hunting hours?", "\"Legal shooting time began 22 minutes later.\""), .direct("How far was the blind from the ramp?", "\"Less than 200 yards from a public boat ramp.\""), .direct("What did {DL} say?", "\"That {D} saw a low shape in the mist and thought it was ducks.\""), .direct("What did you learn about the timing of the shot compared with legal shooting hours?", "\"Legal shooting time began twenty-two minutes after the shot was fired. {D} fired before legal light, into mist, at a boat that sat less than 200 yards from a public boat ramp.\""), .cross("Did you hear what the partner said?", "\"Only afterward, when I interviewed the partner. The partner says a warning was given.\""), .cross("Was the boat visible from the blind?", "\"It sat under a camouflage tarp with no lights, which made it very hard to see.\""), .cross("Did {DL} call 911?", "\"Yes, but nine minutes after the shot.\""), .cross("Did {DL} stay at the scene?", "\"Yes. {D} stayed and cooperated.\""), .cross("Were hunting hours the issue?", "\"Yes. Shooting time had not begun, which is a violation by itself.\"")],
        defenseRole: "Hunting partner",
        defenseExam: [.direct("How do you know {DL}?", "\"We hunt together every season. I was in the same blind that morning.\""), .direct("What did you see on the water?", "\"A low shape in the mist about a hundred yards out. I could not tell what it was at first.\""), .direct("Did {DL} react to your warning?", "\"I do not think {D} heard me. The shot came right after.\""), .direct("What happened after the shot?", "\"Silence, and then {D} ran out and called out. {D} looked sick when we saw the boat.\""), .direct("How did {DL} act after?", "\"Shocked and horrified. {D} could not stop saying how sorry {D.he} was.\""), .direct("What did you say to {D} before the shot, and what did you see on the water?", "\"I said that might be a boat, hold your fire. I saw a low shape in the mist about a hundred yards out, but {D} had already pulled the trigger.\""), .cross("Did you say your warning loudly?", "\"Not loudly. I kept my voice low because we were hunting.\""), .cross("Did {DL} look at you when you spoke?", "\"I do not think so. {D} was looking at the lake.\""), .cross("Was it before legal shooting time?", "\"Yes. I knew it was early.\""), .cross("Did you try to stop {DL} from shooting?", "\"I did not grab the gun. It happened too fast.\""), .cross("Could either of you see lights on the boat?", "\"No. There were none.\"")],
        theory: ("{D} fired into the mist before legal light near a boat ramp.", "A tragic mistake by an experienced hunter in poor visibility."),
